tools.example:
M = 16;
nSym = 10000;
data = randi([0 M-1], nSym, 1);
tx = qammod(data, M, 'gray', 'UnitAveragePower', true);
rx = awgn(tx, 18, 'measured');
rxData = qamdemod(rx, M, 'gray', 'UnitAveragePower', true);
fprintf('SER = %.4f\n', symerr(data, rxData)/nSym);

M = 64; k = log2(M);
bits = randi([0 1], 6000, 1);
tx = qammod(bits, M, 'InputType', 'bit', 'UnitAveragePower', true);
snr = 22;
nvar = 10^(-snr/10);
rx = awgn(tx, snr, 'measured');
llr = qamdemod(rx, M, 'OutputType', 'approxllr', ...
    'NoiseVariance', nvar, 'UnitAveragePower', true);
hard = double(llr < 0);
fprintf('BER = %.5f\n', biterr(bits, hard)/numel(bits));

M = 4;
data = randi([0 M-1], 5000, 1);
tx = pskmod(data, M, pi/4, 'gray');
rx = awgn(tx, 10, 'measured');
scatterplot(rx)
rxData = pskdemod(rx, M, pi/4, 'gray');
fprintf('SER = %.4f\n', symerr(data, rxData)/numel(data));

M = 8;
bits = randi([0 1], 9000, 1);
tx = pskmod(bits, M, 0, 'gray', 'InputType', 'bit');
rx = awgn(tx, 14, 'measured');
llr = pskdemod(rx, M, 0, 'gray', 'OutputType', 'approxllr', ...
    'NoiseVariance', 10^(-14/10));
hat = double(llr < 0);
fprintf('BER = %.5f\n', biterr(bits, hat)/numel(bits));

nfft = 128; cplen = 16;
nullidx = [1:6 64 123:128]';
numDataCarriers = nfft - numel(nullidx);
numSym = 10;
data = qammod(randi([0 15], numDataCarriers, numSym), 16, 'UnitAveragePower', true);
txWave = ofdmmod(data, nfft, cplen, nullidx);
fprintf('Waveform length: %d samples\n', numel(txWave));

nfft = 128; cplen = 16;
nullidx = [1:6 64 123:128]';
data = qammod(randi([0 15], 115, 10), 16, 'UnitAveragePower', true);
tx = ofdmmod(data, nfft, cplen, nullidx);
rx = awgn(tx, 25, 'measured');
rxGrid = ofdmdemod(rx, nfft, cplen, cplen/2, nullidx);
evm = comm.EVM;
fprintf('EVM: %.2f%%\n', evm(data(:), rxGrid(:)));

M = 4;
EbNo = 0:2:12;
ber = zeros(size(EbNo));
for k = 1:numel(EbNo)
    data = randi([0 M-1], 1e5, 1);
    tx = pskmod(data, M, pi/4);
    snr = EbNo(k) + 10*log10(log2(M));
    rx = awgn(tx, snr, 'measured');
    ber(k) = symerr(data, pskdemod(rx, M, pi/4)) / 1e5;
end
semilogy(EbNo, ber, 'o-'); grid on

chan = comm.AWGNChannel('NoiseMethod', 'Signal to noise ratio (Eb/No)', ...
    'EbNo', 6, 'BitsPerSymbol', 2, 'SamplesPerSymbol', 4, 'Seed', 42, ...
    'RandomStream', 'mt19937ar with seed');
errRate = comm.ErrorRate;
for frame = 1:100
    data = randi([0 3], 1000, 1);
    tx = pskmod(data, 4, pi/4);
    rx = chan(repelem(tx, 4, 1));
    rxSym = pskdemod(rx(1:4:end), 4, pi/4);
    stats = errRate(data, rxSym);
end
fprintf('SER = %.5f\n', stats(1));

fs = 1e6;
chan = comm.RayleighChannel('SampleRate', fs, ...
    'PathDelays', [0 1.5e-6 3.2e-6], ...
    'AveragePathGains', [0 -3 -6], ...
    'MaximumDopplerShift', 50, ...
    'PathGainsOutputPort', true, 'Seed', 7, 'RandomStream', 'mt19937ar with seed');
tx = pskmod(randi([0 3], 10000, 1), 4, pi/4);
[rx, gains] = chan(tx);
plot(20*log10(abs(gains(:,1))))
ylabel('Path 1 gain (dB)')

chan = comm.RicianChannel('SampleRate', 1e6, ...
    'PathDelays', [0 2e-6], 'AveragePathGains', [0 -5], ...
    'KFactor', 8, 'MaximumDopplerShift', 30, ...
    'DirectPathDopplerShift', 20);
tx = qammod(randi([0 15], 20000, 1), 16, 'UnitAveragePower', true);
rx = chan(tx);
scatterplot(rx(1:2000))

beta = 0.25; span = 8; sps = 4;
h = rcosdesign(beta, span, sps, 'sqrt');
data = randi([0 3], 500, 1);
sym = pskmod(data, 4, pi/4);
tx = upfirdn(sym, h, sps);
rx = upfirdn(tx, h, 1, sps);
rx = rx(span+1 : end-span);
scatterplot(rx)

sps = 8;
txf = comm.RaisedCosineTransmitFilter('RolloffFactor', 0.25, ...
    'FilterSpanInSymbols', 10, 'OutputSamplesPerSymbol', sps);
rxf = comm.RaisedCosineReceiveFilter('RolloffFactor', 0.25, ...
    'FilterSpanInSymbols', 10, 'InputSamplesPerSymbol', sps, ...
    'DecimationFactor', sps);
sym = qammod(randi([0 15], 2000, 1), 16, 'UnitAveragePower', true);
tx = txf(sym);
rx = rxf(awgn(tx, 25, 'measured'));
eyediagram(tx(1:800), 2*sps)

sps = 4;
rxf = comm.RaisedCosineReceiveFilter('RolloffFactor', 0.3, ...
    'FilterSpanInSymbols', 8, 'InputSamplesPerSymbol', sps, ...
    'DecimationFactor', 2);   % 2 samples/symbol for the synchronizer
rxOversampled = rxf(rxWaveform);

M = 16; k = log2(M);
data = randi([0 M-1], 50000, 1);
tx = qammod(data, M, 'UnitAveragePower', true);
rx = awgn(tx, 15, 'measured');
rxData = qamdemod(rx, M, 'UnitAveragePower', true);
[nErr, ber] = biterr(data, rxData, k);
fprintf('%d bit errors, BER = %.5f\n', nErr, ber);

M = 8;
data = randi([0 M-1], 20000, 1);
rx = pskdemod(awgn(pskmod(data, M), 12, 'measured'), M);
[nSymErr, ser] = symerr(data, rx);
[nBitErr, ber] = biterr(data, rx, log2(M));
fprintf('SER = %.5f, BER = %.5f (ratio %.2f)\n', ser, ber, ser/ber);

EbNo = 0:1:14;
berTheory16 = berawgn(EbNo, 'qam', 16);
berTheory4 = berawgn(EbNo, 'psk', 4, 'nondiff');
semilogy(EbNo, berTheory16, '-', EbNo, berTheory4, '--')
grid on; xlabel('E_b/N_0 (dB)'); ylabel('BER')
legend('16-QAM','QPSK')

trellis = poly2trellis(7, [171 133]);      % rate-1/2 NASA standard code
fprintf('States: %d, rate 1/%d\n', trellis.numStates, trellis.numOutputSymbols/2);
data = randi([0 1], 10000, 1);
coded = convenc(data, trellis);
recursive = poly2trellis(4, [13 15], 13);

trellis = poly2trellis(7, [171 133]);
data = randi([0 1], 5000, 1);
coded = convenc(data, trellis);
fprintf('Rate: %.2f\n', numel(data)/numel(coded));
puncpat = [1;1;0;1;1;0];       % rate 3/4
codedPunc = convenc(data, trellis, puncpat);

trellis = poly2trellis(7, [171 133]);
data = randi([0 1], 20000, 1);
coded = convenc(data, trellis);
modulated = pskmod(coded, 2);
rx = awgn(modulated, 4, 'measured');
llr = pskdemod(rx, 2, 0, 'OutputType', 'llr', 'NoiseVariance', 10^(-4/10));
decoded = vitdec(llr, trellis, 34, 'trunc', 'unquant');
fprintf('BER after decoding: %.5f\n', biterr(data, decoded)/numel(data));

H = dvbs2ldpc(3/4);
enc = comm.LDPCEncoder(H);
dec = comm.LDPCDecoder(H, 'MaximumIterationCount', 50, ...
    'IterationTerminationCondition', 'Parity check satisfied');
msg = randi([0 1], size(H,2) - size(H,1), 1);
cw = enc(msg);
rx = awgn(pskmod(cw, 2), 1.5, 'measured');
llr = pskdemod(rx, 2, 0, 'OutputType', 'llr', 'NoiseVariance', 10^(-1.5/10));
rxMsg = dec(llr);
fprintf('Errors: %d\n', sum(msg ~= rxMsg));

trellis = poly2trellis(4, [13 15], 13);
n = 1024;
rng(0); intrlvrIdx = randperm(n)';
tEnc = comm.TurboEncoder(trellis, intrlvrIdx);
tDec = comm.TurboDecoder(trellis, intrlvrIdx, 6);
data = randi([0 1], n, 1);
cw = tEnc(data);
rx = awgn(pskmod(cw, 2), 0, 'measured');
llr = pskdemod(rx, 2, 0, 'OutputType', 'llr', 'NoiseVariance', 1);
out = tDec(-llr);
fprintf('Errors: %d\n', sum(data ~= out));

gen = comm.CRCGenerator('Polynomial', 'z^16 + z^12 + z^5 + 1', ...
    'InitialConditions', 1, 'FinalXOR', 1);
det = comm.CRCDetector('Polynomial', 'z^16 + z^12 + z^5 + 1', ...
    'InitialConditions', 1, 'FinalXOR', 1);
msg = randi([0 1], 200, 1);
cw = gen(msg);
cw(50) = ~cw(50);            % inject an error
[out, err] = det(cw);
fprintf('Error detected: %d\n', err);

m = 8; n = 255; k = 223;      % standard RS(255,223)
msg = gf(randi([0 2^m-1], 10, k), m);
code = rsenc(msg, n, k);
noisy = code;
noisy(1, 1:16) = noisy(1, 1:16) + gf(randi([1 255], 1, 16), m);
[decoded, cnumerr] = rsdec(noisy, n, k);
fprintf('Errors corrected in row 1: %d\n', cnumerr(1));

m = 4; n = 15; k = 9;        % corrects up to 3 symbol errors
msg = gf(randi([0 15], 5, k), m);
code = rsenc(msg, n, k);
rx = code;
rx(:, 1:3) = rx(:, 1:3) + gf(randi([1 15], 5, 3), m);
[dec, cnumerr] = rsdec(rx, n, k);
fprintf('Corrected per codeword: %s\n', mat2str(cnumerr'));
isequal(dec, msg)

errRate = comm.ErrorRate('ReceiveDelay', 0);
M = 16;
for frame = 1:200
    data = randi([0 M-1], 1000, 1);
    tx = qammod(data, M, 'UnitAveragePower', true);
    rx = awgn(tx, 16, 'measured');
    rxData = qamdemod(rx, M, 'UnitAveragePower', true);
    stats = errRate(data, rxData);
end
fprintf('SER = %.5f over %d symbols\n', stats(1), stats(3));

pn = comm.PNSequence('Polynomial', 'x^7 + x^3 + 1', ...
    'InitialConditions', [1 0 0 0 0 0 0], 'SamplesPerFrame', 127);
seq = pn();
r = xcorr(2*seq-1, 'normalized');
plot(-126:126, r)
fprintf('Peak-to-sidelobe: %.1f\n', max(r)/max(r(abs(-126:126) > 0)));

M = 16; sps = 4;
sym = qammod(randi([0 M-1], 2000, 1), M, 'UnitAveragePower', true);
h = rcosdesign(0.25, 8, sps);
tx = upfirdn(sym, h, sps);
rx = upfirdn(awgn(tx, 22, 'measured'), h, 1, sps);
scatterplot(rx(9:end-8), 1, 0, 'b.')
title('16-QAM after matched filtering')

sps = 8;
sym = pskmod(randi([0 3], 500, 1), 4, pi/4);
h = rcosdesign(0.35, 6, sps);
tx = upfirdn(sym, h, sps);
eyediagram(tx(50:50+200*sps), 2*sps)
noisy = awgn(tx, 18, 'measured');
eyediagram(noisy(50:50+200*sps), 2*sps)

M = 16;
refC = qammod(0:M-1, M, 'UnitAveragePower', true);
constDiag = comm.ConstellationDiagram('ReferenceConstellation', refC, ...
    'ShowReferenceConstellation', true, 'Title', '16-QAM RX', ...
    'XLimits', [-1.5 1.5], 'YLimits', [-1.5 1.5]);
for frame = 1:50
    tx = qammod(randi([0 M-1], 500, 1), M, 'UnitAveragePower', true);
    constDiag(awgn(tx, 20, 'measured'));
end
release(constDiag);
